<?php namespace App\Http\Controllers; use App\Models\{Initiative,Opportunity}; use App\Services\CommercialJourneyService; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\View\View;
class CommercialJourneyController extends Controller { public function index():View{return view('commercial.index',['initiatives'=>Initiative::query()->where('origin','commercial')->with('opportunity')->get()]);} public function show(Initiative $initiative):View{abort_unless($initiative->origin->value==='commercial',404);return view('commercial.show',['initiative'=>$initiative,'opportunity'=>$initiative->opportunity()->with(['assessments','proposals.versions','negotiations'])->first()]);} public function storeOpportunity(Request $r,Initiative $initiative,CommercialJourneyService $s):RedirectResponse{$data=$r->validate(['title'=>'required|string|max:200','summary'=>'nullable|string','priority'=>'required|in:low,normal,high','estimated_value'=>'nullable|numeric','expected_decision_at'=>'nullable|date','commercial_owner_id'=>'nullable|integer']);$s->createOpportunity($initiative,$data,$r->user());return back()->with('success','Oportunidade criada.');} public function assessment(Request $r,Opportunity $o,CommercialJourneyService $s):RedirectResponse{$s->assessment($o,$r->validate(['state'=>'required|in:draft,preparing,performed,consolidated,validated,cancelled','needs'=>'nullable|string','constraints'=>'nullable|string','assumptions'=>'nullable|string','objectives'=>'nullable|string','participants'=>'nullable|string','observations'=>'nullable|string']),$r->user());return back();} public function proposal(Request $r,Opportunity $o,CommercialJourneyService $s):RedirectResponse{$s->proposal($o,$r->validate(['scope_summary'=>'nullable|string','solution_summary'=>'nullable|string','pricing_model'=>'nullable|string','estimated_value'=>'nullable|numeric','change_reason'=>'nullable|string']),$r->user());return back();} public function negotiation(Request $r,Opportunity $o,CommercialJourneyService $s):RedirectResponse{$s->negotiation($o,$r->validate(['interaction_type'=>'required|in:meeting,email,phone,counterproposal,internal_analysis,decision,acceptance','occurred_at'=>'required|date','summary'=>'nullable|string','counterproposal'=>'nullable|string','decision'=>'nullable|string','next_step'=>'nullable|string']),$r->user());return back();} public function transition(Request $r,Opportunity $o,CommercialJourneyService $s):RedirectResponse{$d=$r->validate(['state'=>'required|in:qualified,under_discovery,under_proposal,under_negotiation,won,lost,suspended','justification'=>'nullable|string']);$s->transition($o,$d['state'],$r->user(),$d['justification']??null);return back();}}
